1	syntax = "proto3";
2	
3	package memos.api.v1;
4	
5	import "api/v1/user_service.proto";
6	import "google/api/annotations.proto";
7	import "google/api/client.proto";
8	import "google/api/field_behavior.proto";
9	import "google/api/resource.proto";
10	import "google/protobuf/empty.proto";
11	import "google/protobuf/field_mask.proto";
12	import "google/protobuf/timestamp.proto";
13	import "google/type/color.proto";
14	
15	option go_package = "gen/api/v1";
16	
17	service InstanceService {
18	  // Gets the instance profile.
19	  rpc GetInstanceProfile(GetInstanceProfileRequest) returns (InstanceProfile) {
20	    option (google.api.http) = {get: "/api/v1/instance/profile"};
21	  }
22	
23	  // Gets an instance setting.
24	  rpc GetInstanceSetting(GetInstanceSettingRequest) returns (InstanceSetting) {
25	    option (google.api.http) = {get: "/api/v1/{name=instance/settings/*}"};
26	    option (google.api.method_signature) = "name";
27	  }
28	
29	  // Batch gets instance settings.
30	  rpc BatchGetInstanceSettings(BatchGetInstanceSettingsRequest) returns (BatchGetInstanceSettingsResponse) {
31	    option (google.api.http) = {
32	      post: "/api/v1/instance/settings:batchGet"
33	      body: "*"
34	    };
35	  }
36	
37	  // Updates an instance setting.
38	  rpc UpdateInstanceSetting(UpdateInstanceSettingRequest) returns (InstanceSetting) {
39	    option (google.api.http) = {
40	      patch: "/api/v1/{setting.name=instance/settings/*}"
41	      body: "setting"
42	    };
43	    option (google.api.method_signature) = "setting,update_mask";
44	  }
45	
46	  // Tests notification email delivery with the provided or stored SMTP settings.
47	  rpc TestInstanceEmailSetting(TestInstanceEmailSettingRequest) returns (google.protobuf.Empty) {
48	    option (google.api.http) = {
49	      post: "/api/v1/instance/settings/notification:testEmail"
50	      body: "*"
51	    };
52	  }
53	
54	  // GetInstanceStats returns resource usage statistics for the instance. Admin only.
55	  rpc GetInstanceStats(GetInstanceStatsRequest) returns (InstanceStats) {
56	    option (google.api.http) = {get: "/api/v1/instance/stats"};
57	  }
58	}
59	
60	// Instance profile message containing basic instance information.
61	message InstanceProfile {
62	  // Version is the current version of instance.
63	  string version = 2;
64	
65	  // Demo indicates if the instance is in demo mode.
66	  bool demo = 3;
67	
68	  // Instance URL is the URL of the instance.
69	  string instance_url = 6;
70	
71	  // The first administrator who set up this instance, for display purposes.
72	  // May be null on an instance that has lost all admins; use needs_setup to
73	  // determine whether initial setup is actually required.
74	  User admin = 7;
75	
76	  // Commit is the current build commit of instance.
77	  string commit = 8;
78	
79	  // NeedsSetup is true when the instance has no users yet and requires initial
80	  // setup (creating the first admin account). Unlike a null admin, this stays
81	  // false once any user exists, so an instance that has lost its admins is not
82	  // mistaken for a fresh install.
83	  bool needs_setup = 9;
84	}
85	
86	// Request for instance profile.
87	message GetInstanceProfileRequest {}
88	
89	// An instance setting resource.
90	message InstanceSetting {
91	  option (google.api.resource) = {
92	    type: "memos.api.v1/InstanceSetting"
93	    pattern: "instance/settings/{setting}"
94	    singular: "instanceSetting"
95	    plural: "instanceSettings"
96	  };
97	
98	  // The name of the instance setting.
99	  // Format: instance/settings/{setting}
100	  string name = 1 [(google.api.field_behavior) = IDENTIFIER];
101	
102	  oneof value {
103	    GeneralSetting general_setting = 2;
104	    StorageSetting storage_setting = 3;
105	    MemoRelatedSetting memo_related_setting = 4;
106	    TagsSetting tags_setting = 5;
107	    NotificationSetting notification_setting = 6;
108	    AISetting ai_setting = 7;
109	  }
110	
111	  // Enumeration of instance setting keys.
112	  enum Key {
113	    KEY_UNSPECIFIED = 0;
114	    // GENERAL is the key for general settings.
115	    GENERAL = 1;
116	    // STORAGE is the key for storage settings.
117	    STORAGE = 2;
118	    // MEMO_RELATED is the key for memo related settings.
119	    MEMO_RELATED = 3;
120	    // TAGS is the key for tag metadata.
121	    TAGS = 4;
122	    // NOTIFICATION is the key for notification transport settings.
123	    NOTIFICATION = 5;
124	    // AI is the key for AI provider settings.
125	    AI = 6;
126	  }
127	
128	  // General instance settings configuration.
129	  message GeneralSetting {
130	    // disallow_user_registration disallows user registration.
131	    bool disallow_user_registration = 2;
132	    // disallow_password_auth disallows password authentication.
133	    bool disallow_password_auth = 3;
134	    // additional_script is the additional script.
135	    string additional_script = 4;
136	    // additional_style is the additional style.
137	    string additional_style = 5;
138	    // custom_profile is the custom profile.
139	    CustomProfile custom_profile = 6;
140	    // week_start_day_offset is the week start day offset from Sunday.
141	    // 0: Sunday, 1: Monday, 2: Tuesday, 3: Wednesday, 4: Thursday, 5: Friday, 6: Saturday
142	    // Default is Sunday.
143	    int32 week_start_day_offset = 7;
144	
145	    // disallow_change_username disallows changing username.
146	    bool disallow_change_username = 8;
147	    // disallow_change_nickname disallows changing nickname.
148	    bool disallow_change_nickname = 9;
149	
150	    // Custom profile configuration for instance branding.
151	    message CustomProfile {
152	      string title = 1;
153	      string description = 2;
154	      string logo_url = 3;
155	    }
156	  }
157	
158	  // Storage configuration settings for instance attachments.
159	  message StorageSetting {
160	    // Storage type enumeration for different storage backends.
161	    enum StorageType {
162	      STORAGE_TYPE_UNSPECIFIED = 0;
163	      // DATABASE is the database storage type.
164	      DATABASE = 1;
165	      // LOCAL is the local storage type.
166	      LOCAL = 2;
167	      // S3 is the S3 storage type.
168	      S3 = 3;
169	    }
170	    // storage_type is the storage type.
171	    StorageType storage_type = 1;
172	    // The template of file path.
173	    // e.g. assets/{timestamp}_{filename}
174	    string filepath_template = 2;
175	    // The max upload size in megabytes.
176	    int64 upload_size_limit_mb = 3;
177	
178	    // S3 configuration for cloud storage backend.
179	    // Reference: https://developers.cloudflare.com/r2/examples/aws/aws-sdk-go/
180	    message S3Config {
181	      string access_key_id = 1;
182	      string access_key_secret = 2 [(google.api.field_behavior) = INPUT_ONLY];
183	      string endpoint = 3;
184	      string region = 4;
185	      string bucket = 5;
186	      bool use_path_style = 6;
187	      // insecure_skip_tls_verify disables TLS certificate verification when connecting
188	      // to the S3 endpoint. Only enable this for trusted endpoints that use a self-signed
189	      // certificate; it removes protection against man-in-the-middle attacks.
190	      bool insecure_skip_tls_verify = 7;
191	    }
192	    // The S3 config.
193	    S3Config s3_config = 4;
194	  }
195	
196	  // Memo-related instance settings and policies.
197	  message MemoRelatedSetting {
198	    reserved 2;
199	    reserved "display_with_update_time";
200	    // content_length_limit is the limit of content length. Unit is byte.
201	    int32 content_length_limit = 3;
202	    // enable_double_click_edit enables editing on double click.
203	    bool enable_double_click_edit = 4;
204	    // reactions is the list of reactions.
205	    repeated string reactions = 7;
206	  }
207	
208	  // Metadata for a tag.
209	  message TagMetadata {
210	    // Optional background color for the tag label.
211	    // When unset, the default tag color is used.
212	    google.type.Color background_color = 1;
213	    // Whether memos with this tag should have their content blurred.
214	    bool blur_content = 2;
215	  }
216	
217	  // Tag metadata configuration.
218	  // Active tag metadata is stored in per-user tag settings.
219	  // This message remains for backward compatibility with existing clients and migrations.
220	  message TagsSetting {
221	    // Map of tag name pattern to tag metadata.
222	    // Each key is treated as an anchored regular expression (^pattern$),
223	    // so a single entry like "project/.*" matches all tags under that prefix.
224	    // Exact tag names are also valid (they are trivially valid regex patterns).
225	    map<string, TagMetadata> tags = 1;
226	  }
227	
228	  // Notification transport configuration.
229	  message NotificationSetting {
230	    EmailSetting email = 1;
231	
232	    // Email delivery configuration for notifications.
233	    message EmailSetting {
234	      bool enabled = 1;
235	      string smtp_host = 2;
236	      int32 smtp_port = 3;
237	      string smtp_username = 4;
238	      string smtp_password = 5 [(google.api.field_behavior) = INPUT_ONLY];
239	      string from_email = 6;
240	      string from_name = 7;
241	      string reply_to = 8;
242	      bool use_tls = 9;
243	      bool use_ssl = 10;
244	    }
245	  }
246	
247	  // AI provider configuration settings.
248	  message AISetting {
249	    // providers is the list of AI provider configurations available instance-wide.
250	    repeated AIProviderConfig providers = 1;
251	
252	    // transcription is the speech-to-text feature configuration.
253	    // When unset or transcription.provider_id is empty, transcription is disabled.
254	    TranscriptionConfig transcription = 2;
255	  }
256	
257	  // AIProviderConfig represents one callable AI provider connection.
258	  message AIProviderConfig {
259	    string id = 1;
260	    string title = 2;
261	    AIProviderType type = 3;
262	    string endpoint = 4;
263	    // api_key is write-only and is never returned by GetInstanceSetting.
264	    string api_key = 5 [(google.api.field_behavior) = INPUT_ONLY];
265	    // api_key_set indicates whether an API key is stored for this provider.
266	    bool api_key_set = 8 [(google.api.field_behavior) = OUTPUT_ONLY];
267	    // api_key_hint is a masked hint for the stored API key.
268	    string api_key_hint = 9 [(google.api.field_behavior) = OUTPUT_ONLY];
269	  }
270	
271	  // AIProviderType is the provider implementation type.
272	  enum AIProviderType {
273	    AI_PROVIDER_TYPE_UNSPECIFIED = 0;
274	    OPENAI = 1;
275	    GEMINI = 2;
276	  }
277	
278	  // TranscriptionConfig configures the speech-to-text feature.
279	  message TranscriptionConfig {
280	    // provider_id references an entry in AISetting.providers[].id.
281	    // Empty string means transcription is disabled.
282	    string provider_id = 1;
283	
284	    // model is the provider-specific model identifier.
285	    // Empty string falls back to the engine default
286	    // (whisper-1 for OPENAI providers, gemini-2.5-flash for GEMINI providers).
287	    string model = 2;
288	
289	    // language is the default ISO 639-1 language hint sent to the provider.
290	    // Empty string lets the provider auto-detect.
291	    string language = 3;
292	
293	    // prompt is a default spelling/vocabulary hint passed to the provider.
294	    string prompt = 4;
295	  }
296	}
297	
298	// Request message for GetInstanceSetting method.
299	message GetInstanceSettingRequest {
300	  // The resource name of the instance setting.
301	  // Format: instance/settings/{setting}
302	  string name = 1 [
303	    (google.api.field_behavior) = REQUIRED,
304	    (google.api.resource_reference) = {type: "memos.api.v1/InstanceSetting"}
305	  ];
306	}
307	
308	// Request message for BatchGetInstanceSettings method.
309	message BatchGetInstanceSettingsRequest {
310	  // The resource names of the instance settings.
311	  // Format: instance/settings/{setting}
312	  repeated string names = 1 [
313	    (google.api.field_behavior) = REQUIRED,
314	    (google.api.resource_reference) = {type: "memos.api.v1/InstanceSetting"}
315	  ];
316	}
317	
318	// Response message for BatchGetInstanceSettings method.
319	message BatchGetInstanceSettingsResponse {
320	  // The instance settings in the same order as the input names.
321	  repeated InstanceSetting settings = 1;
322	}
323	
324	// Request message for UpdateInstanceSetting method.
325	message UpdateInstanceSettingRequest {
326	  // The instance setting resource which replaces the resource on the server.
327	  InstanceSetting setting = 1 [(google.api.field_behavior) = REQUIRED];
328	
329	  // The list of fields to update.
330	  google.protobuf.FieldMask update_mask = 2 [(google.api.field_behavior) = OPTIONAL];
331	}
332	
333	// Request message for TestInstanceEmailSetting method.
334	message TestInstanceEmailSettingRequest {
335	  // Optional. SMTP email settings to test. If omitted, the stored notification email setting is used.
336	  InstanceSetting.NotificationSetting.EmailSetting email = 1 [(google.api.field_behavior) = OPTIONAL];
337	
338	  // Optional. Recipient email address. If omitted, the current user's email address is used.
339	  string recipient_email = 2 [(google.api.field_behavior) = OPTIONAL];
340	}
341	
342	// Request message for GetInstanceStats.
343	message GetInstanceStatsRequest {}
344	
345	// Resource usage statistics for the instance.
346	message InstanceStats {
347	  DatabaseStats database = 1;
348	  // Recursive size of the data directory in bytes. -1 if unavailable.
349	  int64 local_storage_bytes = 2;
350	  // Server-side timestamp when the snapshot was generated.
351	  google.protobuf.Timestamp generated_time = 4;
352	
353	  // Database size statistics.
354	  message DatabaseStats {
355	    // driver is one of "sqlite", "mysql", "postgres".
356	    string driver = 1;
357	    // size_bytes is the database size in bytes; -1 if unavailable.
358	    int64 size_bytes = 2;
359	  }
360	}
